#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Locks sponsors.mia.cx/admin behind Cloudflare Access: creates (or updates) the Access app through the
# Cloudflare API, then gives the Worker the values it uses to check Access logins itself.
# Run from the repository root: bash scripts/setup-access.sh

TOTAL_STAGES=4
ACCOUNT_ID=492214885e7a580ccc1d141dfdb4dc5f
HOST=sponsors.mia.cx
APP_NAME="Sponsor ads admin"
API="https://api.cloudflare.com/client/v4/accounts/$ACCOUNT_ID"
for tool in curl jq pnpm; do
  command -v "$tool" >/dev/null 2>&1 || { printf '%sThis wizard needs %s.%s\n' "$RED" "$tool" "$RESET"; exit 1; }
done
cf() { curl -sS -H "Authorization: Bearer $ACCESS_API_TOKEN" -H 'Content-Type: application/json' "$@"; }
cf_error() { jq -r '[.errors[]?.message] | join("; ") | if . == "" then "unknown error" else . end' <<<"$1"; }
wrangler_secret() {
  if printf '%s' "$2" | pnpm exec wrangler secret put "$1" >/dev/null 2>&1; then
    printf '  %s✓ set%s Worker secret %s\n' "$GREEN" "$RESET" "$1"
  else
    SKIPPED+=("Worker secret $1 (pnpm exec wrangler secret put $1)")
    warn "couldn't set Worker secret $1"
  fi
}

banner "Cloudflare Access for $HOST/admin"

stage "Cloudflare: a token that can manage Access"
say "This token is only used while the wizard runs. It isn't saved anywhere."
open_url "https://dash.cloudflare.com/profile/api-tokens"
step "Click 'Create Token', then 'Get started' next to 'Create Custom Token'. Name it: Access setup."
step "Permissions: Account → Access: Apps and Policies → Edit."
step "Click '+ Add more': Account → Access: Organizations, Identity Providers, and Groups → Read."
step "Account Resources: Include → mia.cx. Set a short TTL (end date tomorrow) if you like."
step "Click 'Continue to summary', then 'Create Token', and copy the token."
ask_secret ACCESS_API_TOKEN "Paste the token:"
check=$(cf "$API/access/apps?per_page=1")
if [[ "$(jq -r .success <<<"$check")" != true ]]; then
  warn "Cloudflare refused the token: $(cf_error "$check")"
  exit 1
fi
printf '  %s✓ the token can read Access apps%s\n' "$GREEN" "$RESET"
pause

stage "Zero Trust team"
say "Access needs a Zero Trust team on the mia.cx account. Its login page lives at <team>.cloudflareaccess.com."
while :; do
  org=$(cf "$API/access/organizations")
  TEAM_DOMAIN=$(jq -r '.result.auth_domain // empty' <<<"$org")
  [[ -n "$TEAM_DOMAIN" ]] && break
  warn "No Zero Trust team on this account yet."
  open_url "https://one.dash.cloudflare.com/$ACCOUNT_ID"
  step "Pick a team name, choose the Free plan, and finish the setup steps."
  pause "Press Enter when the team exists"
done
TEAM_DOMAIN="https://${TEAM_DOMAIN#https://}"
printf '  %s✓ team domain:%s %s\n' "$GREEN" "$RESET" "$TEAM_DOMAIN"
pause

stage "Create the Access app"
ask ADMIN_EMAIL "Email address that may open the dashboard:"
[[ "$ADMIN_EMAIL" == *@* ]] || { warn "That doesn't look like an email address."; exit 1; }
say "Access will ask for a one-time code sent to $ADMIN_EMAIL before $HOST/admin loads."
body=$(jq -n --arg name "$APP_NAME" --arg host "$HOST" --arg email "$ADMIN_EMAIL" '{
  name: $name, type: "self_hosted", domain: "\($host)/admin",
  destinations: [{type: "public", uri: "\($host)/admin"}, {type: "public", uri: "\($host)/api/admin"}],
  session_duration: "24h", app_launcher_visible: false,
  policies: [{name: "Only Mia", decision: "allow", include: [{email: {email: $email}}]}]
}')
existing=$(cf "$API/access/apps?per_page=100" | jq -r --arg name "$APP_NAME" '.result[]? | select(.name == $name) | .id' | head -n1)
if [[ -n "$existing" ]]; then
  confirm "An app called '$APP_NAME' already exists. Replace its settings?" || exit 1
  res=$(cf -X PUT "$API/access/apps/$existing" --data "$body")
else
  confirm "Create the Access app for $HOST/admin and $HOST/api/admin?" || exit 1
  res=$(cf -X POST "$API/access/apps" --data "$body")
fi
if [[ "$(jq -r .success <<<"$res")" != true ]]; then
  warn "Cloudflare couldn't save the app: $(cf_error "$res")"
  exit 1
fi
ACCESS_AUD=$(jq -r '.result.aud' <<<"$res")
printf '  %s✓ Access app saved%s (audience tag %s…)\n' "$GREEN" "$RESET" "${ACCESS_AUD:0:8}"
pause

stage "Tell the Worker and check"
say "The Worker checks each Access login itself, using the team domain and the app's audience tag."
wrangler_secret ACCESS_TEAM_DOMAIN "$TEAM_DOMAIN"
wrangler_secret ACCESS_AUD "$ACCESS_AUD"
say "Waiting a few seconds for Access to take effect…"
sleep 5
status=$(curl -s -o /dev/null -w '%{http_code} %{redirect_url}' "https://$HOST/admin/")
if [[ "$status" == 302*cloudflareaccess.com* ]]; then
  printf '  %s✓ %s/admin now sends visitors to the Access login%s\n' "$GREEN" "$HOST" "$RESET"
else
  warn "Expected a redirect to the Access login, got: $status. Access can take a minute; open https://$HOST/admin to check."
fi
open_url "https://$HOST/admin/"
say "Sign in with the code Access emails to $ADMIN_EMAIL. The dashboard should load."
note "You can delete the 'Access setup' token now: https://dash.cloudflare.com/profile/api-tokens"
pause "Press Enter to finish"

finish
